import {VerifiedHTMLDiv} from '@github-ui/safe-html/VerifiedHTML'
import {PlayIcon} from '@primer/octicons-react'

import styles from './ActionLogo.module.css'
import type {MarketplaceItem} from './types'

interface ActionLogoProps {
  action: MarketplaceItem
  className?: string
}

export function ActionLogo({action, className = ''}: ActionLogoProps) {
  const {color, iconSvg} = action

  return (
    <div
      data-testid="logo"
      aria-hidden="true"
      className={`flex-shrink-0 rounded-3 overflow-hidden ${styles.ActionLogo} ${className}`}
      style={{
        backgroundColor: `#${color}`,
        color: color.toLowerCase() === 'ffffff' ? 'var(--fgColor-black)' : 'var(--fgColor-white)',
      }}
    >
      {iconSvg ? (
        <VerifiedHTMLDiv html={iconSvg} className={styles.ActionLogoSvg} />
      ) : (
        <PlayIcon className={styles.ActionLogoSvg} />
      )}
    </div>
  )
}
