import {Link} from '@github-ui/react-core/link'
import {LawIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {clsx} from 'clsx'

import styles from './LicenseSelector.module.css'

export default function LicenseSelector({url, className}: {url: string; className?: string}) {
  return (
    <Button variant="invisible" as={Link} to={url} leadingVisual={LawIcon} className={clsx(className, styles.Button)}>
      Choose a license template
    </Button>
  )
}
