import {AlertFillIcon, ChevronLeftIcon, ChevronRightIcon, StarIcon} from '@primer/octicons-react'
import {ActionList, Breadcrumbs, Button, Spinner, Truncate} from '@primer/react'
import {useEffect, useRef, useState} from 'react'

import {ActionLogo} from './ActionLogo'
import {MarketplaceItemDetail} from './MarketplaceItemDetail'
import styles from './MarketplacePanel.module.css'
import type {FeaturedCategory, MarketplaceItem} from './types'
import type {Pagination} from './use-marketplace-data'

interface MarketplacePanelProps {
  src?: string
  items?: MarketplaceItem[]
  categories?: FeaturedCategory[]
  loading?: boolean
  fetching?: boolean
  error?: boolean
  searchQuery?: string
  onSearchChange?: (value: string) => void
  pagination?: Pagination
  onPageChange?: (page: number) => void
  selectedCategory?: FeaturedCategory | null
  onCategorySelect?: (category: FeaturedCategory) => void
  onCategoryClear?: () => void
}

function MarketplaceList({
  items,
  error,
  loading,
  hasSearch,
  label,
  onSelect,
}: {
  items?: MarketplaceItem[]
  error?: boolean
  loading?: boolean
  hasSearch?: boolean
  label: string
  onSelect: (item: MarketplaceItem) => void
}) {
  if (error) {
    return (
      <div className={styles.Error} data-testid="marketplace-panel-error">
        <AlertFillIcon />
        <span>There was a problem loading the actions from the marketplace.</span>
      </div>
    )
  }

  if (loading) {
    return (
      <div className={styles.Loading} data-testid="marketplace-panel-loading">
        <Spinner size="small" srText={hasSearch ? 'Searching Marketplace' : 'Loading featured actions'} />
      </div>
    )
  }

  if (hasSearch && items?.length === 0) {
    return (
      <div className={styles.Empty} data-testid="marketplace-panel-empty">
        <span>No results found. Try a different search.</span>
      </div>
    )
  }

  return (
    <ActionList aria-label={label}>
      {items?.map(item => (
        <ActionList.Item key={item.id} onSelect={() => onSelect(item)}>
          <ActionList.LeadingVisual>
            <ActionLogo action={item} />
          </ActionList.LeadingVisual>
          {item.name}
          {item.ownerLogin && <span className={styles.Owner}> by {item.ownerLogin}</span>}
          <ActionList.Description variant="block">{item.description}</ActionList.Description>
          <ActionList.TrailingVisual>
            <span className={styles.Stars}>
              <StarIcon /> {item.stargazerCount}
            </span>
          </ActionList.TrailingVisual>
        </ActionList.Item>
      ))}
    </ActionList>
  )
}

function MarketplacePagination({
  pagination,
  fetching,
  onPageChange,
}: {
  pagination: Pagination
  fetching?: boolean
  onPageChange?: (page: number) => void
}) {
  const {previousPage, nextPage} = pagination
  const [pendingDirection, setPendingDirection] = useState<'previous' | 'next' | null>(null)

  // clear the pending direction once the background fetch settles
  if (!fetching && pendingDirection !== null) {
    setPendingDirection(null)
  }

  if (previousPage === null && nextPage === null) {
    return null
  }

  const previousLoading = fetching && pendingDirection === 'previous'
  const nextLoading = fetching && pendingDirection === 'next'

  return (
    <nav className={styles.Pagination} aria-label="Search results pages" data-testid="marketplace-panel-pagination">
      <Button
        size="small"
        leadingVisual={ChevronLeftIcon}
        loading={previousLoading}
        disabled={previousPage === null || fetching}
        onClick={() => {
          if (previousPage === null) return
          setPendingDirection('previous')
          onPageChange?.(previousPage)
        }}
      >
        Previous
      </Button>
      <Button
        size="small"
        trailingVisual={ChevronRightIcon}
        loading={nextLoading}
        disabled={nextPage === null || fetching}
        onClick={() => {
          if (nextPage === null) return
          setPendingDirection('next')
          onPageChange?.(nextPage)
        }}
      >
        Next
      </Button>
    </nav>
  )
}

function FeaturedCategories({
  categories,
  onCategorySelect,
}: {
  categories: FeaturedCategory[]
  onCategorySelect?: (category: FeaturedCategory) => void
}) {
  return (
    <>
      <h2 className={styles.SectionHeader}>Featured categories</h2>

      <div className={styles.PanelSection}>
        <div className={styles.CategoriesGrid}>
          {categories.map(category => (
            <button
              key={category.slug}
              type="button"
              className={styles.CategoryButton}
              aria-label={`Search Marketplace for ${category.name} Actions`}
              onClick={() => onCategorySelect?.(category)}
            >
              {category.name}
            </button>
          ))}
        </div>

        <a className={styles.BrowseAllLink} href="/marketplace?type=actions" target="_blank" rel="noopener noreferrer">
          Browse all actions on the GitHub Marketplace
        </a>
      </div>
    </>
  )
}

export function MarketplacePanel({
  src,
  items,
  categories,
  loading,
  fetching,
  error,
  searchQuery = '',
  onSearchChange,
  pagination,
  onPageChange,
  selectedCategory,
  onCategorySelect,
  onCategoryClear,
}: MarketplacePanelProps) {
  const [selectedItem, setSelectedItem] = useState<MarketplaceItem | null>(null)
  const headingRef = useRef<HTMLHeadingElement>(null)
  const hasMountedRef = useRef(false)
  const hasSearch = searchQuery.trim().length > 0
  const hasCategory = !!selectedCategory
  const isScoped = hasSearch || hasCategory
  const categorySlug = selectedCategory?.slug ?? null

  // selecting or clearing a category unmounts the control, which drops the focus to <body>. We need to manually move
  // focus to the panel heading so focus is preserved and screen reader users hear the new context.
  useEffect(() => {
    if (!hasMountedRef.current) {
      hasMountedRef.current = true
      return
    }
    headingRef.current?.focus()
  }, [categorySlug])

  const showPagination =
    isScoped && !loading && !error && pagination && (pagination.previousPage !== null || pagination.nextPage !== null)
  const showCategories = !isScoped && categories && categories.length > 0

  if (selectedItem) {
    return (
      <div className={styles.PanelSection}>
        <MarketplaceItemDetail src={src} item={selectedItem} onBack={() => setSelectedItem(null)} />
      </div>
    )
  }

  const heading = hasSearch || hasCategory ? 'Search results' : 'Featured actions'
  const searchLabel = hasCategory
    ? `Search Marketplace for ${selectedCategory.name} Actions`
    : 'Search Marketplace for Actions'

  return (
    <>
      <div className={styles.PanelSection}>
        <input
          type="text"
          className="form-control input-block input-contrast"
          placeholder={searchLabel}
          aria-label={searchLabel}
          value={searchQuery}
          onChange={event => onSearchChange?.(event.target.value)}
        />
      </div>

      {hasCategory && (
        <div className={`${styles.PanelSection} ${styles.CategoryBreadcrumbs}`}>
          <Breadcrumbs>
            <Breadcrumbs.Item
              as="button"
              type="button"
              className={styles.BackCrumb}
              onClick={() => onCategoryClear?.()}
            >
              All categories
            </Breadcrumbs.Item>
            <Breadcrumbs.Item as="span" selected>
              <Truncate maxWidth="150px" title={selectedCategory.name} inline>
                {selectedCategory.name}
              </Truncate>
            </Breadcrumbs.Item>
          </Breadcrumbs>
        </div>
      )}

      <h2 ref={headingRef} tabIndex={-1} className={styles.SectionHeader}>
        {heading}
      </h2>

      <MarketplaceList
        items={items}
        loading={loading}
        error={error}
        hasSearch={isScoped}
        label={heading}
        onSelect={setSelectedItem}
      />

      {showPagination && (
        <MarketplacePagination pagination={pagination} fetching={fetching} onPageChange={onPageChange} />
      )}
      {showCategories && <FeaturedCategories categories={categories} onCategorySelect={onCategorySelect} />}
    </>
  )
}
