import {useCodeViewAddQueuedBanner} from '@github-ui/code-view-shared/contexts/CodeViewBannersContext'
import type {SaveResponse, SaveResponseErrorDetails, WebCommitInfo} from '@github-ui/code-view-types'
import {useCurrentRepository} from '@github-ui/current-repository'
import {useFileTreeControlContext} from '@github-ui/repos-file-tree-view'
import type {BypassMetadata} from '@github-ui/secret-scanning'
import {resetMemoizeFetchJSON} from '@github-ui/use-latest-commit'
import {useNavigate} from '@github-ui/use-navigate'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {WebCommitDialog as CommitDialog, type WebCommitDialogState} from '@github-ui/web-commit-dialog'
import React, {useEffect} from 'react'

import type {useGenerateCommitMessageInfo} from '../../hooks/use-generate-commit-message'
import {useGenerateCommitMessage} from '../../hooks/use-generate-commit-message'
import {loadFileTreePath} from '../../queries/file-tree-query'
import {
  useTrackWebCommitAcceptance,
  useTrackWebCommitRegenerated,
} from '../../utilities/generate-commit-message-helpers'
import {pollUntilCommitHasQuorum} from './utilities/fetch-is-commit-available'

interface ISaveBlobData {
  message: string
  placeholder_message: string
  description: string
  author_email?: string
  'commit-choice'?: string
  target_branch?: string
  quick_pull: string
  guidance_task: string
  commit: string
  same_repo?: number
  pr: string
}

interface IEditSaveBlobData extends ISaveBlobData {
  content_changed: boolean
  filename: string
  new_filename: string
  value: string
}

interface IDeleteSaveBlobData extends ISaveBlobData {
  _method: string
}

// states and transitions:
// closed
//  -> pending
// pending
//  -> closed
//  -> saving
// saving
//  -> saved
//  -> pending
//  -> closed

export default function WebCommitDialog(props: {
  content?: string
  contentChanged?: boolean
  fileName?: string
  isDelete: boolean
  isNewFile: boolean
  helpUrl: string
  oldPath?: string
  ownerName: string
  placeholderMessage: string
  refName: string
  generateCommitMessageInfo?: useGenerateCommitMessageInfo
  returnFocusRef: React.RefObject<HTMLElement | null>
  webCommitInfo: WebCommitInfo
  dialogState: WebCommitDialogState
  setDialogState: (state: WebCommitDialogState) => void
  setSecretDetected?: (secretDetected: boolean) => void
  setSecretBypassMetadata?: (bypassMetadata: BypassMetadata) => void
}) {
  const {
    content,
    contentChanged,
    fileName,
    isDelete,
    isNewFile,
    oldPath,
    ownerName,
    placeholderMessage,
    refName,
    generateCommitMessageInfo,
    webCommitInfo,
    setDialogState,
    setSecretDetected,
    setSecretBypassMetadata,
  } = props

  const {
    authorEmails,
    canCommitStatus,
    commitOid,
    defaultEmail,
    defaultNewBranchName,
    forkedRepo,
    guidanceTask,
    pr,
    repoHeadEmpty,
    saveUrl,
  } = webCommitInfo
  const navigate = useNavigate()

  const trackWebCommitAcceptance = useTrackWebCommitAcceptance()
  const trackWebCommitRegenerated = useTrackWebCommitRegenerated()
  const repo = useCurrentRepository()

  const [generatedMessages, setGeneratedMessages] = React.useState<string[]>([])
  const [regenerateCallCount, setRegenerateCallCount] = React.useState(0)

  const {generatedCommitMessage, isFetching} = useGenerateCommitMessage(
    placeholderMessage,
    generateCommitMessageInfo?.copilotGenerateCommitMessageAuthInfo,
    generateCommitMessageInfo?.initialPath,
    generateCommitMessageInfo?.completeFilePath,
    generateCommitMessageInfo?.initialFileContent,
    content,
    isNewFile,
    generatedMessages,
    regenerateCallCount,
  )

  const generateCommitMessageEnabled =
    generateCommitMessageInfo?.copilotGenerateCommitMessageAuthInfo?.copilotAccessAllowed
  const generatingCommitMessage = generateCommitMessageEnabled && isFetching

  const [message, setMessage] = React.useState(generatingCommitMessage ? '' : placeholderMessage)
  const [description, setDescription] = React.useState('')
  const [showingGeneratedCommitMessage, setShowingGeneratedCommitMessage] = React.useState(false)
  const [showingGeneratedCommitDescription, setShowingGeneratedCommitDescription] = React.useState(false)
  const [userCancelledCopilotCommitGeneration, setUserCancelledCopilotCommitGeneration] = React.useState(false)
  const [hasShownGeneratedCommitMessage, setHasShownGeneratedCommitMessage] = React.useState(false)

  // Auto-populate commit message when generation completes
  useEffect(() => {
    if (generatedCommitMessage?.commitMessage && !isFetching && !userCancelledCopilotCommitGeneration) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setMessage(generatedCommitMessage.commitMessage)
      setShowingGeneratedCommitMessage(generatedCommitMessage.commitMessage !== placeholderMessage)
      if (!hasShownGeneratedCommitMessage) {
        setHasShownGeneratedCommitMessage(generatedCommitMessage.commitMessage !== placeholderMessage)
      }

      // Track previously generated messages when regenerating to try to avoid repeating the same messages
      let uniqueGeneratedMessages = generatedMessages
      if (!generatedMessages.includes(generatedCommitMessage.commitMessage)) {
        // If this isn't a duplicate message adding it to generatedMessages should be enough to trigger a refetch
        uniqueGeneratedMessages = [...generatedMessages, generatedCommitMessage.commitMessage]
        setGeneratedMessages(uniqueGeneratedMessages)
      }

      if (regenerateCallCount > 0) {
        trackWebCommitRegenerated({
          version: '1',
          regenerateCallCount,
          uniquelyGeneratedMessagesCount: uniqueGeneratedMessages.length,
        })
      }

      // If the description is empty we still need to set it to clear any previous description
      if (generatedCommitMessage?.description !== undefined) {
        setDescription(generatedCommitMessage.description)

        if (generatedCommitMessage?.description) {
          setShowingGeneratedCommitDescription(true)
        }
      }
    }
  }, [
    generatedCommitMessage?.commitMessage,
    generatedCommitMessage?.description,
    isFetching,
    placeholderMessage,
    userCancelledCopilotCommitGeneration,
    hasShownGeneratedCommitMessage,
    generatedMessages,
    regenerateCallCount,
    trackWebCommitRegenerated,
  ])

  const [isQuickPull, setIsQuickPull] = React.useState(canCommitStatus !== 'allowed' || !!forkedRepo)
  const [prTargetBranch, setPRTargetBranch] = React.useState(defaultNewBranchName)
  const [authorEmail, setAuthorEmail] = React.useState(authorEmails.length ? defaultEmail : undefined)
  const [errorMessage, setErrorMessage] = React.useState('')
  const [errorDetails, setErrorDetails] = React.useState<SaveResponseErrorDetails>()
  const {refreshTree} = useFileTreeControlContext()
  const addQueuedBanner = useCodeViewAddQueuedBanner()

  const commitMessageInputRef = React.useRef<HTMLInputElement>(null)
  useEffect(() => {
    if (commitMessageInputRef.current) {
      commitMessageInputRef.current.focus()
    }
  }, [])

  const quickPullChoice = !forkedRepo && !repoHeadEmpty

  // Reset generated messages when dialog state changes to closed or saved (to clear on new dialog session)
  useEffect(() => {
    if (props.dialogState === 'closed' || props.dialogState === 'saved') {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setGeneratedMessages([])
    }
  }, [props.dialogState])

  const handleCopilotCommitGenerationInterruption = React.useCallback(() => {
    // If the user interacts with the message or description input
    // we should stop copilot from generating an allow them to input their own message/description
    // only set this on the first interaction
    if (!userCancelledCopilotCommitGeneration) {
      setUserCancelledCopilotCommitGeneration(true)
    }
  }, [userCancelledCopilotCommitGeneration])

  const handleCopilotRegenerateCommitMessage = React.useCallback(() => {
    if (!userCancelledCopilotCommitGeneration && !isFetching) {
      // Reset state when regenerating
      setMessage('')
      setShowingGeneratedCommitMessage(false)
      setDescription('')
      setShowingGeneratedCommitDescription(false)
      // This actually triggers a refetch because the regenerateCount is part of the query key
      setRegenerateCallCount(prev => prev + 1)
    }
  }, [userCancelledCopilotCommitGeneration, isFetching])

  const showGeneratingCommitMessageLoading = generatingCommitMessage && !userCancelledCopilotCommitGeneration

  const showGeneratingCommitMessageLoaded =
    generateCommitMessageEnabled && (showingGeneratedCommitMessage || showingGeneratedCommitDescription) && !isFetching

  const onSave = async () => {
    setDialogState('saving')

    // TODO: Guidance task
    const quickPullBase = forkedRepo ? `${ownerName}:${refName}` : refName

    const sharedData: ISaveBlobData = {
      message,
      // eslint-disable-next-line camelcase
      placeholder_message: placeholderMessage,
      description,
      // eslint-disable-next-line camelcase
      author_email: authorEmail ?? undefined,
      'commit-choice': quickPullChoice ? (isQuickPull ? 'quick-pull' : 'direct') : undefined,
      // eslint-disable-next-line camelcase
      target_branch: quickPullChoice ? (isQuickPull ? prTargetBranch : refName) : undefined,
      // eslint-disable-next-line camelcase
      quick_pull: isQuickPull ? quickPullBase : '',
      // eslint-disable-next-line camelcase
      guidance_task: guidanceTask ?? '',
      commit: commitOid,
      // eslint-disable-next-line camelcase
      same_repo: !forkedRepo && !repoHeadEmpty ? 1 : undefined,
      pr: pr ?? '',
    }

    let data: ISaveBlobData

    if (isDelete) {
      // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion -- assertion required for type narrowing; removing it breaks tsc
      data = {...sharedData, _method: 'delete'} as IDeleteSaveBlobData
    } else {
      data = {
        ...sharedData,
        // eslint-disable-next-line camelcase
        content_changed: contentChanged,
        filename: isNewFile ? fileName : oldPath,
        // eslint-disable-next-line camelcase
        new_filename: fileName,
        value: content,
      } as IEditSaveBlobData
    }

    const formData = new FormData()
    for (const [key, dataValue] of Object.entries(data)) {
      if (dataValue !== undefined) {
        formData.set(key, dataValue)
      }
    }

    try {
      const result = await verifiedFetch(saveUrl, {
        method: 'post',
        body: formData,
        headers: {Accept: 'application/json'},
      })

      const json: SaveResponse = await result.json()

      if (json.data.commitQuorumPollPath) {
        await pollUntilCommitHasQuorum(json.data.commitQuorumPollPath)
      }

      // on a successful save, we are redirected to either back to the blob, back the PR, or to a quick pull PR
      if (json.data.redirect) {
        // Track acceptance async if user committed and if they accepted the generated or placeholder commit messages
        trackWebCommitAcceptance({
          message: data.message,
          description: data.description,
          placeholderMessage,
          generatedCommitMessage,
          showingGeneratedCommitMessage,
          showingGeneratedCommitDescription,
          isNewFile,
          isDelete,
          contentChanged,
          oldPath,
          fileName,
          content,
          regenerateCallCount,
          // Tracking versions in https://github.com/github/rmw-team/issues/1149; latest: 1
          version: '1',
        })

        const redirectUrl = json.data.redirect
        const url = redirectUrl.startsWith(window.location.origin)
          ? redirectUrl.replace(window.location.origin, '')
          : redirectUrl

        // Reset the latest commit cache so that the next time the user navigates to the blob, they see the latest commit
        resetMemoizeFetchJSON()

        // Refresh the file tree if the file name changed.
        if (refreshTree?.current !== undefined) {
          // eslint-disable-next-line react-hooks/immutability
          refreshTree.current = true
        }

        // fetch directory to update file tree view
        if (fileName) {
          try {
            await loadFileTreePath({
              owner: repo.ownerLogin,
              repo: repo.name,
              branch: refName,
              path: fileName,
            })
          } catch {
            // do nothing
          }
        }

        if (json.data.message) {
          addQueuedBanner({message: json.data.message, variant: 'default'})
        }

        setDialogState('saved')

        // sometimes react will not have updated the dialog state before the redirect happens
        // so we need to wait a bit for the state to update before redirecting
        setTimeout(() => {
          navigate(url)
        }, 50)

        return
      } else if (json.data.error && json.data.secretBypassMetadata) {
        setSecretDetected?.(true)
        setSecretBypassMetadata?.(json.data.secretBypassMetadata)
        setDialogState('closed')
      } else if (json.data.error) {
        setDialogState('pending')
        setErrorMessage(json.data.error)
        if (json.data.error_details) {
          setErrorDetails(json.data.error_details)
        }
      } else {
        setErrorMessage('File could not be edited')
        setDialogState('pending')
      }
    } catch {
      setErrorMessage('File could not be edited')
      setDialogState('pending')
    }
  }

  // remove nulls from author emails

  // Use the danger button type if a user has to bypass rules to commit

  return (
    <CommitDialog
      onSave={onSave}
      {...{
        message,
        setMessage,
        description,
        setDescription,
        isQuickPull,
        setIsQuickPull,
        prTargetBranch,
        setPRTargetBranch,
        setAuthorEmail,
        errorMessage,
        errorDetails,
        isFetching,
        showGeneratingCommitMessageLoading,
        showGeneratingCommitMessageLoaded,
        hasShownGeneratedCommitMessage,
        onCopilotCommitGenerationCancel: handleCopilotCommitGenerationInterruption,
        onRegenerateCommitMessageClick: handleCopilotRegenerateCommitMessage,
      }}
      {...props}
    />
  )
}
