import {
  acceptCompletion,
  type Completion,
  type CompletionContext,
  type CompletionResult,
  insertCompletionText,
  pickedCompletion,
  selectedCompletion,
  startCompletion,
} from '@codemirror/autocomplete'
import type {Command, EditorView} from '@codemirror/view'
import {autocomplete} from '@github-ui/code-mirror/autocomplete'
import {helpPanelConstructor} from '@github-ui/code-mirror/help-panel'
import {getCursor, getIndentationUnit, getLine, offsetToPos} from '@github-ui/code-mirror/utils'

import type {Snippet, Suggestion} from './autocomplete-types'
import {getIndentation, replaceWhitespaces} from './utils'
import {isMacOS} from '@github-ui/get-os'
import {html, render} from 'lit-html'

interface CustomCompletion extends Completion {
  snippet: Snippet
  from: number
  to: number
}

/**
 * Extended Completion interface for language service completions.
 * Adds properties to support completion chaining and proper sorting.
 */
export interface LanguageServiceCompletion extends Completion {
  /** The actual text inserted, used to detect key completions for chaining */
  insertedText?: string
  /** Sort order for the completion (from language server's sortText) */
  sortText?: string
  /** If true, don't trigger autocomplete after accepting this completion */
  skipChaining?: boolean
}

/**
 * CompletionResult that uses LanguageServiceCompletion for better type safety.
 * Callers should provide completions with `insertedText` for proper chaining behavior.
 */
export interface LanguageServiceCompletionResult extends Omit<CompletionResult, 'options'> {
  options: readonly LanguageServiceCompletion[]
}

export function yamlAutocomplete(completionContext: (context: CompletionContext) => Promise<CompletionResult | null>) {
  return autocomplete(
    completionContext,
    [
      {key: 'Tab', run: acceptCompletionAndStartNext},
      {key: 'Enter', run: acceptCompletionAndStartNext},
    ],
    true, // override enter key for custom behavior
  )
}

/**
 * Compare completions using sortText for proper ordering.
 * This respects the language server's sortText convention (e.g., "runs-on 1", "runs-on 2").
 */
export function compareCompletionsBySortText(a: Completion, b: Completion): number {
  const aSort = (a as LanguageServiceCompletion).sortText ?? a.label
  const bSort = (b as LanguageServiceCompletion).sortText ?? b.label
  return aSort.localeCompare(bSort)
}

/**
 * Determines if we should chain completions after accepting a completion.
 * Returns true for key completions (text containing ": " or ":\n") or list markers.
 *
 * Examples that trigger chaining:
 *   "runs-on: "    → cursor ready for inline value (e.g., ubuntu-latest)
 *   "strategy:\n"  → cursor ready for nested map keys
 *   "steps:\n  - " → cursor ready for sequence item keys (e.g., uses, run)
 *   "\n  - "       → escape hatch "switch to list" - cursor ready for list item value
 */
export function shouldChainCompletion(completion: Completion): boolean {
  const lsCompletion = completion as LanguageServiceCompletion

  // Some completions (like snippets) explicitly disable chaining
  if (lsCompletion.skipChaining) {
    return false
  }

  const appliedText =
    lsCompletion.insertedText ?? (typeof completion.apply === 'string' ? completion.apply : completion.label)

  // Chain after colon+whitespace (key completions) or list markers
  return /:\s/.test(appliedText) || /- $/.test(appliedText)
}

/**
 * Autocomplete configuration for language service integration.
 * Features:
 * - activateOnTyping: Shows completions automatically as the user types
 * - activateOnCompletion: After accepting a completion that ends with `: ` or `:\n`,
 *   automatically triggers completions for the value
 */
export function yamlAutocompleteLanguageService(
  completionContext: (context: CompletionContext) => Promise<LanguageServiceCompletionResult | null>,
) {
  // Command that accepts completion and conditionally starts next
  const acceptCompletionAndMaybeStartNext: Command = (view: EditorView) => {
    const selected = selectedCompletion(view.state)

    if (selected) {
      acceptCompletion(view)
      // Only chain if the predicate says so
      if (shouldChainCompletion(selected)) {
        startCompletion(view)
      }
      return true
    }

    return false
  }

  return autocomplete(
    completionContext,
    [
      {key: 'Tab', run: acceptCompletionAndMaybeStartNext},
      {key: 'Enter', run: acceptCompletionAndMaybeStartNext},
    ],
    true, // override enter key for custom behavior
    compareCompletionsBySortText, // use language server's sortText for ordering
  )
}

export function yamlHelpPanel() {
  return helpPanelConstructor(autocompleteHelpPanel())
}

export function buildCompletions(suggestions: Suggestion[], cursor: number) {
  const completions: CustomCompletion[] = suggestions.map(suggestion => {
    return {
      label: suggestion.displayText,
      detail: suggestion.description,
      from: suggestion.replace ? cursor - suggestion.replace.length : cursor,
      to: cursor,
      apply: applySnippet,
      snippet: suggestion.snippet,
    }
  })

  const from = completions.length > 0 ? completions[0]!.from : cursor

  return {
    from,
    options: completions,
    filter: false,
  }
}

function applySnippet(view: EditorView, completion: Completion) {
  const {snippet} = completion as CustomCompletion
  return insertSnippet(view, completion, snippet, true)
}

function insertSnippet(view: EditorView, completion: Completion, snippet: Snippet, indent: boolean) {
  const {tokens} = snippet

  const tab = getIndentationUnit(view)

  for (let i = 0; i < tokens.length; i += 2) {
    const cursor = getCursor(view)
    const offset = offsetToPos(view, cursor.from)
    const ind = indent ? getIndentation(getLine(view, offset.line + 1).text) : ''

    const token = replaceWhitespaces(tokens[i]!, tab, ind)

    view.dispatch({
      ...insertCompletionText(view.state, token, view.state.selection.main.from, view.state.selection.main.to),
    })
  }

  // let codemirror know that we're done with the completion
  view.dispatch({
    annotations: pickedCompletion.of(completion),
  })
}

const acceptCompletionAndStartNext: Command = (view: EditorView) => {
  const selected = selectedCompletion(view.state) // the completion is active

  if (selected) {
    // if there is a selected completion, accept it and try to start the next one
    acceptCompletion(view)
    startCompletion(view)

    return true
  }

  // let this pass through to the default keymap
  return false
}

function autocompleteHelpPanel() {
  const dom = document.createElement('div')
  dom.className = 'cm-help-panel border-top'
  dom.setAttribute('data-testid', 'yaml-editor-help-footer')

  const appleShortcuts = isMacOS() ? html`or <kbd>Option + Space</kbd>` : html``

  const helpContent = html`
    <div id="yaml-editor-help-default">
      Use <kbd>Control + Space</kbd>
      ${appleShortcuts} to trigger autocomplete in most situations.
    </div>
    <div id="yaml-editor-help" hidden>
      <span className="js-yaml-editor-help-placeholder pr-1" />
      <span className="js-yaml-editor-help-tab"> Use <kbd>Tab</kbd> to navigate to the next placeholder. </span>
    </div>
  `

  render(helpContent, dom)

  return dom
}
